// 第五轮 · Bootloader 直连恢复（官方 JYM001 包）：设备拔插后停在 Bootloader，
// 应用「打开」会同步失败但保留通道；选官方包 → 开始 → 轮询。用于恢复 App 并验证信息区已初始化。
(async () => {
  const B64 = '';
  const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const clean = (node) => node?.textContent?.replace(/\s+/g, ' ').trim() ?? null;
  const field = (name) => clean(document.querySelector(`[data-field="${name}"]`));
  const out = { timeline: [] };
  const snap = () => ({
    at: new Date().toISOString().slice(11, 23),
    phase: clean(document.querySelector('.fw-phase')),
    percent: clean(document.querySelector('.fw-percent')),
    block: clean(document.querySelector('.fw-block')),
    errorHidden: document.querySelector('.fw-error')?.hidden ?? null,
    error: clean(document.querySelector('.fw-error-title')),
    detail: clean(document.querySelector('.fw-error-detail')),
    resultHidden: document.querySelector('.fw-result')?.hidden ?? null,
    done: clean(document.querySelector('.fw-done')),
  });

  window.__micstudioGo('device');
  await wait(300);
  document.querySelector('.segmented .seg-btn[data-value="native"]')?.click();
  await wait(200);
  document.querySelector('.device-actions .btn')?.click();
  await wait(1600);
  const row = Array.from(document.querySelectorAll('.device-row')).find((item) => (item.textContent ?? '').includes('0A67'));
  if (!row) return JSON.stringify({ error: '设备列表里没有 0A67' });
  row.querySelector('.btn')?.click();
  await wait(9000);
  out.afterOpen = {
    source: clean(document.querySelector('#source-pill')),
    sync: clean(document.querySelector('#sync-pill')),
    error: clean(document.querySelector('.device-error')),
    fwButton: Boolean(document.querySelector('.fw-open')),
  };
  document.querySelector('.fw-open')?.click();
  await wait(700);
  if (!document.querySelector('.fw-view')) return JSON.stringify({ ...out, error: '固件抽屉没有打开' });

  const bin = atob(B64);
  const bytes = new Uint8Array(bin.length);
  for (let index = 0; index < bin.length; index += 1) bytes[index] = bin.charCodeAt(index);
  const file = new File([bytes], 'dfu_M001 MCU V0.0.4_2026-11-03_Rev0.bin', { type: 'application/octet-stream' });
  const input = document.querySelector('.fw-file');
  if (!input) return JSON.stringify({ ...out, error: '找不到 .fw-file' });
  const transfer = new DataTransfer();
  transfer.items.add(file);
  input.files = transfer.files;
  input.dispatchEvent(new Event('change', { bubbles: true }));
  await wait(2000);
  out.preflight = {
    model: field('model'),
    version: field('version'),
    blocks: field('blocks'),
    checksum: field('checksum'),
    errorHidden: document.querySelector('.fw-error')?.hidden ?? null,
    error: clean(document.querySelector('.fw-error-title')),
    startDisabled: document.querySelector('.fw-start')?.disabled ?? null,
  };
  if (out.preflight.errorHidden === false) return JSON.stringify(out);

  const confirm = document.querySelector('.fw-confirm input[type="checkbox"]');
  if (!confirm) return JSON.stringify({ ...out, error: '找不到确认开关' });
  confirm.click();
  await wait(300);
  const start = document.querySelector('.fw-start');
  if (!start || start.disabled) return JSON.stringify({ ...out, error: '开始按钮不可用', state: snap() });
  start.click();
  out.startedAt = new Date().toISOString().slice(11, 23);

  let last = '';
  let lastChange = Date.now();
  const deadline = Date.now() + 8 * 60 * 1000;
  while (Date.now() < deadline) {
    await wait(300);
    const now = snap();
    const key = `${now.phase}|${now.block}|${now.percent}`;
    if (key !== last) {
      last = key;
      lastChange = Date.now();
      out.timeline.push(now);
    }
    if (now.errorHidden === false || now.resultHidden === false) {
      out.final = now;
      break;
    }
    if (Date.now() - lastChange > 45000) {
      out.stalled = now;
      break;
    }
  }
  out.final = out.final ?? snap();
  out.timeline = out.timeline.slice(-120);

  window.__micstudioGo('device');
  await wait(800);
  out.diag = {
    stats: Object.fromEntries(Array.from(document.querySelectorAll('[data-stat]')).map((node) => [node.dataset.stat, clean(node)])),
    tail: Array.from(document.querySelectorAll('.diag-log-row')).map((node) => clean(node)).slice(-30),
  };
  out.pills = { source: clean(document.querySelector('#source-pill')), sync: clean(document.querySelector('#sync-pill')) };
  return JSON.stringify(out);
})()